### Part 3: WordPress Script for Single Resource

To embed a specific resource (like the Personal Financial Statement), use this version of the script. Note the change in `appUrl` which now includes the `#/embed/[RESOURCE_ID]` path.

**To get your Resource ID:**
Go to your Admin Dashboard, look at your resources. The ID is the string associated with that resource in your Firestore (usually a mix of letters and numbers).

```html
<div id="single-resource-embed" style="width: 100%; max-width: 800px; margin: 0 auto;"></div>

<script>
(function() {
    // REPLACE THIS ID with the actual ID from your Admin Dashboard
    var resourceId = 'INSERT_RESOURCE_ID_HERE'; 
    var appUrl = 'https://financialresourcelibraryv3-fmhm.vercel.app/#/embed/' + resourceId;

    var container = document.getElementById('single-resource-embed');
    if (!container) return;

    var iframe = document.createElement('iframe');
    iframe.src = appUrl;
    iframe.style.width = '100%';
    iframe.style.height = '300px'; // Short starting height for a single card
    iframe.style.border = 'none';
    iframe.style.overflow = 'hidden';
    iframe.scrolling = 'no';
    iframe.title = 'Financial Resource';

    container.appendChild(iframe);

    window.addEventListener('message', function(event) {
        if (event.origin !== 'https://financialresourcelibraryv3-fmhm.vercel.app') return;
        if (event.data && event.data.type === 'financial-library-resize') {
            iframe.style.height = (event.data.height + 10) + 'px';
        }
    }, false);
})();
</script>

